# -*- coding: utf-8 -*-
from common import md, esc, cq, wq
T=[("d1","👑","升天的基督藉圣灵与圣道作王","使徒行传的主角是升天的基督：祂从父领受圣灵并浇灌下来（{{徒2:33}}），坐在父右边为主为基督（{{徒2:36}}），把得救的人天天加给教会（{{徒2:47}}）。教会的一切能力来自坐王的基督，而非组织或技巧。","徒1:1-11；2:33-36；7:55-56；9:4-5；23:11",[("hc",50),("hc",51)],('wcf',8,1)),
  ("d2","🔥","五旬节：救赎历史中一次性的事件","五旬节像十字架和复活一样是**救赎历史（historia salutis）的里程碑**，不会重复。圣灵降临的四个场景（耶路撒冷 2 章、撒马利亚 8 章、外邦人 10 章、约翰门徒 19 章）标记福音跨越的四道边界，不是每个信徒“第二次祝福”的模板。今天信徒一信主就领受圣灵（{{罗8:9}}；{{林前12:13}}）。","徒2；8:14-17；10:44-48；11:15-18；19:1-7",[("hc",53)],None),
  ("d3","⏳","使徒职分与神迹恩赐：根基已立","使徒必须是主复活的见证人（{{徒1:21-22}}），由主亲自拣选；他们与先知是教会的**根基**（{{弗2:20}}），根基只立一次。神迹是“使徒的凭据”（{{林后12:12}}），证实新启示。圣经正典完成后，神不再以从前的方式启示祂的旨意——这是改革宗**恩赐终止论**的立场（Gaffin, *Perspectives on Pentecost*）。神仍然行事、医治、听祷告，但不再藉新的使徒或先知加添圣经。","徒1:21-26；2:43；5:12；14:3；19:11；来2:3-4",[("bc",7,"我们相信，圣经中包含了神全部的旨意；我们也相信它对人得救所必须信的一切真理作了充分的教导。")],('wcf',1,1,"由于神不再使用以前那些方式向祂的百姓启示自己的旨意了")),
  ("d4","📖","道的兴旺：讲道是首要的蒙恩之道","使徒把“专心以祈祷传道为事”放在首位（{{徒6:4}}）；六个进展报告的主语是“道”。圣灵藉着所传的道使人重生（{{徒10:44}}：“彼得还说这话的时候，圣灵降在一切听道的人身上”）。","徒2:41-42；4:4,31；6:2-7；8:4；12:24；13:44-49；19:20；20:32",[("hc",65),("dort",3,17,"神以他的全能创造和维系我们肉身生命时并不排除，反倒需要使用一些方法。")],None),
  ("d5","🌷","神主权的恩典：拣选与有效呼召","“凡预定得永生的人都信了”（{{徒13:48}}）；“主就开导她的心”（{{徒16:14}}）；“神也赐恩给外邦人，叫他们悔改得生命了”（{{徒11:18}}）。同时，使徒迫切劝人、辩论、恳求——神的主权从不取消人的责任与宣教的迫切。","徒2:39,47；5:31；11:18；13:48；16:14；18:10；9:15",[("dort",1,7,"拣选是神不变的旨意。"),("dort",3,10,"神从永恒中就在基督里拣选了属他的百姓，及至时候满足，他便有效地呼召他们，赐他们信心和悔改的能力，救他们脱离黑暗的权势，带领他们进入他爱子的国度。"),("dort",2,5)],None),
  ("d6","⚖️","因信称义，不靠律法","“你们靠摩西的律法，在一切不得称义的事上，信靠这人，就都得称义了”（{{徒13:39}}）；“我们得救乃是因主耶稣的恩”（{{徒15:11}}）。耶路撒冷会议是因信称义的教会会议宣告。","徒10:43；13:38-39；15:1-11；16:31；20:21；26:18",[("bc",22,"我们相信，为了让我们得着关乎这伟大奥秘的真知识，圣灵在我们心中生发真信心。这信心使我们接受耶稣基督并他一切的功德，认他作我们的救主，唯独寻求他的帮助。"),("hc",60)],None),
  ("d7","🏛️","教会的职分、治理与会议","使徒设立执事（6 章）、按立长老（{{徒14:23}}）；长老即监督，受圣灵所立牧养群羊（{{徒20:17,28}}）。耶路撒冷会议（15 章）展示**众教会代表、以圣经为准、共同决议、对众教会有约束力**的会议原则——改革宗（及长老会）区会与大会的圣经根据。","徒6:1-6；11:30；14:23；15；16:4；20:17-35",[("bc",30,"教会须有牧师传讲神的道，并执行圣礼；还须有长老和执事，他们要与牧师一同组成教会议会。"),("bc",31),("bc",32)],('wcf',31,3)),
  ("d8","💧","圣礼：洗礼与擘饼；信徒的家","洗礼紧随信与悔改（{{徒2:38,41}}；{{徒8:36-38}}）；“这应许是给你们和你们的儿女”（{{徒2:39}}）；吕底亚、禁卒、基利司布**全家**受洗或信主（{{徒16:15,33}}；{{徒18:8}}）。七日的第一日擘饼（{{徒20:7}}）。改革宗以此为**婴孩洗礼与约的家庭**的根据之一（与割礼相对应）。","徒2:38-42；8:12-38；10:47-48；16:15,33；18:8；20:7；22:16",[("bc",33,"因此，圣礼是内在不可见之事的外在标记与印证。"),("hc",74)],('wcf',28,4)),
  ("d9","🛡️","教会的标志与纪律","亚拿尼亚与撒非喇（5 章）、行邪术的西门（8 章）显示教会的圣洁与纪律；米利都讲话警告豺狼（20 章）。真教会的标志：纯正的讲道、正确的圣礼、教会纪律——三者在使徒行传都看得见（{{徒2:42}}；{{徒5:11}}）。","徒5:1-11；8:18-24；15:24；20:29-31",[("bc",29,"真教会的标志如下：她宣讲纯正的福音；她按照基督当初设立圣礼的样式施行圣礼；她为纠正错误、刑罚罪恶而执行教会纪律。"),("hc",83)],None),
  ("d10","🏛️","教会与国家","“顺从神，不顺从人，是应当的”（{{徒5:29}}）——有限度的顺服；保罗同时尊重官长（{{徒23:5}}）、使用公民权（{{徒16:37}}；{{徒25:11}}）。路加记录罗马官员一再宣告基督徒无罪。","徒4:19-20；5:29；16:35-39；18:12-17；22:25-29；25:10-12；26:31-32",[("bc",36,"此外，每个人，无论他是什么身份、地位，处于何种境遇，都当顺服执政掌权的，向他们纳税，尊敬他们，并在不违反圣经的一切事上顺服他们。")],None),
  ("d11","🌊","受苦与神的护理","“我们进入神的国，必须经历许多艰难”（{{徒14:22}}）。司提反殉道带来福音的分散（8:4），保罗的捆锁带他到罗马。神的护理使人的恶意成全祂的旨意（{{徒2:23}}；{{徒4:27-28}}）。","徒4:27-28；5:41；8:1-4；12；14:19-22；16:22-34；27",[("hc",27),("hc",28)],None),
  ("d12","🌍","教会的大公性与合一","从五旬节的列国听众（2 章）到埃提阿伯太监、哥尼流、亚略巴古的人：教会是**从各国、各族中**召集出来的一个身体；犹太人与外邦人因同一信心成为一个新人（{{徒15:9}}）。","徒2:5-11；8:27-39；10:34-35；15:7-11；17:26",[("hc",54),("bc",27,"我们相信并宣告圣而公之基督教会，或称普世教会或大公教会。她是真信徒的圣会。")],None)]
def build():
    b=['<div class="dmap glass reveal"><div class="dm-c">🔥 使徒行传<br><small>十二个改革宗主题</small></div><div class="dm-r">'+"".join(f'<a href="#{i}" class="dm-n" style="--i:{k}">{ic} {t}</a>' for k,(i,ic,t,*_) in enumerate(T))+'</div></div>']
    for i,ic,t,s,refs,qs,w in T:
        b.append(f'<h2 id="{i}">{ic} {t}</h2><div class="card glass"><p>{md(s)}</p><p class="refs">📖 主要经文：{esc(refs)}</p></div>')
        b.append('<div class="confs">'+"".join(cq(q) for q in qs)+(wq(w[0],*w[1:]) if w else "")+'</div>')
    b.append('<h2 id="dw">📙 圣灵的工作：五旬节派 vs 改革宗</h2>')
    R=[("圣灵的洗","信主后的第二次经历，以说方言为凭据","重生时一次领受，所有信徒都已受圣灵的洗（{{林前12:13}}）"),("使徒行传的用途","规范性：每个时代应重演","救赎历史的描述：一次性的里程碑，教义由书信确立"),("神迹与方言","今天应常态化","使徒时代证实启示的凭据；神仍掌管医治与护理，但启示性恩赐已停止"),
       ("教会增长","靠能力、经历","靠道与圣灵：讲道、圣礼、祷告与纪律"),("得救确据","常以经历为凭","以神的应许、圣灵内在的见证与成圣的果子为凭（多特信经第五项）")]
    b.append('<div class="tbl"><table><thead><tr><th>议题</th><th>五旬节/灵恩派常见观点</th><th>欧陆改革宗</th></tr></thead><tbody>'+"".join(f'<tr><td><b>{a}</b></td><td>{c}</td><td>{md(d)}</td></tr>' for a,c,d in R)+'</tbody></table></div><p class="note">以上比较针对教义立场，不是评断个人信仰；改革宗承认所有真信徒同属一个大公教会。</p>')
    return "".join(b)
